-- Monthly campaigns: a headline challenge such as Sydney vs Melbourne. People opt in to a side and invite friends.
-- Not one of a person's 3 challenge slots. Steps count from the moment someone joins; sides are compared per walker.
create table if not exists public.campaigns (id uuid primary key default gen_random_uuid(), slug text not null unique, title text not null, tagline text not null default '', side_a text not null, side_b text not null, starts_on date not null, ends_on date not null, active boolean not null default true, created_at timestamptz not null default now());
create table if not exists public.campaign_members (campaign_id uuid not null references public.campaigns(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, side text not null check (side in ('a','b')), joined_on date not null, base int not null default 0, joined_at timestamptz not null default now(), primary key (campaign_id, user_id));
alter table public.campaigns enable row level security; alter table public.campaign_members enable row level security;
create or replace function public.campaign_score(p_campaign uuid, p_user uuid) returns bigint language sql stable security definer set search_path = public as $fn$ select coalesce((select sum(case when s.day = cm.joined_on then greatest(s.steps - cm.base, 0) else s.steps end) from public.step_days s where s.user_id = cm.user_id and s.day >= cm.joined_on and s.day <= c.ends_on), 0)::bigint from public.campaign_members cm join public.campaigns c on c.id = cm.campaign_id where cm.campaign_id = p_campaign and cm.user_id = p_user $fn$;
revoke execute on function public.campaign_score(uuid, uuid) from public, anon, authenticated;
create or replace function public.campaign_now() returns table(id uuid, slug text, title text, tagline text, side_a text, side_b text, days_left integer, a_walkers integer, b_walkers integer, a_total bigint, b_total bigint, my_side text, my_steps bigint) language sql stable security definer set search_path = public as $fn$ with c as (select * from public.campaigns where active and starts_on <= current_date and ends_on >= current_date order by starts_on desc limit 1), sc as (select cm.side, cm.user_id, public.campaign_score(cm.campaign_id, cm.user_id) as s from public.campaign_members cm join c on c.id = cm.campaign_id) select c.id, c.slug, c.title, c.tagline, c.side_a, c.side_b, greatest(0, c.ends_on - current_date + 1)::int, (select count(*) from sc where side = 'a')::int, (select count(*) from sc where side = 'b')::int, coalesce((select sum(s) from sc where side = 'a'), 0)::bigint, coalesce((select sum(s) from sc where side = 'b'), 0)::bigint, (select side from sc where user_id = auth.uid()), coalesce((select s from sc where user_id = auth.uid()), 0)::bigint from c $fn$;
create or replace function public.join_campaign(p_id uuid, p_side text) returns void language plpgsql security definer set search_path = public as $fn$ declare me uuid := auth.uid(); c public.campaigns; base int; begin if me is null then raise exception 'Sign in first'; end if; if p_side not in ('a','b') then raise exception 'Pick a side'; end if; select * into c from public.campaigns where id = p_id and active and starts_on <= current_date and ends_on >= current_date; if c.id is null then raise exception 'That campaign is not running'; end if; if exists (select 1 from public.campaign_members where campaign_id = p_id and user_id = me) then raise exception 'You have already picked a side'; end if; select coalesce(s.steps, 0) into base from public.step_days s where s.user_id = me and s.day = current_date; insert into public.campaign_members (campaign_id, user_id, side, joined_on, base) values (p_id, me, p_side, current_date, coalesce(base, 0)); end $fn$;
create or replace function public.campaign_people(p_id uuid) returns table(display_name text, side text, steps bigint, dog_id uuid, is_me boolean, rank integer) language sql stable security definer set search_path = public as $fn$ with x as (select p.display_name as dn, cm.side as sd, public.campaign_score(p_id, cm.user_id) as s, p.dog_id as dg, cm.user_id as uid from public.campaign_members cm join public.profiles p on p.user_id = cm.user_id where cm.campaign_id = p_id) select x.dn, x.sd, x.s, x.dg, x.uid = auth.uid(), (rank() over (order by x.s desc))::int from x order by x.s desc, x.dn limit 200 $fn$;
revoke execute on function public.campaign_now(), public.join_campaign(uuid, text), public.campaign_people(uuid) from public, anon;
grant execute on function public.campaign_now(), public.join_campaign(uuid, text), public.campaign_people(uuid) to authenticated;
insert into public.campaigns (slug, title, tagline, side_a, side_b, starts_on, ends_on) select 'sydney-v-melbourne', 'Sydney vs Melbourne', 'Which city walks furthest this month? Pick your side and feed more shelter dogs.', 'Sydney', 'Melbourne', c.starts_on, c.ends_on from public.challenge c limit 1 on conflict (slug) do nothing;

-- Any number of sides (cities): campaign_sides holds them; campaign_overview returns them as json, in order.
alter table public.campaign_members drop constraint if exists campaign_members_side_check;
create table if not exists public.campaign_sides (campaign_id uuid not null references public.campaigns(id) on delete cascade, key text not null, label text not null, sort int not null default 0, primary key (campaign_id, key));
alter table public.campaign_sides enable row level security;
insert into public.campaign_sides (campaign_id, key, label, sort) select id, 'a', side_a, 1 from public.campaigns on conflict do nothing;
insert into public.campaign_sides (campaign_id, key, label, sort) select id, 'b', side_b, 2 from public.campaigns on conflict do nothing;
alter table public.campaign_members add constraint campaign_members_side_fk foreign key (campaign_id, side) references public.campaign_sides (campaign_id, key);
create or replace function public.campaign_overview() returns table(id uuid, slug text, title text, tagline text, days_left integer, my_side text, my_steps bigint, sides jsonb) language sql stable security definer set search_path = public as $fn$ with c as (select * from public.campaigns where active and starts_on <= current_date and ends_on >= current_date order by starts_on desc limit 1), sc as (select cm.side, cm.user_id, public.campaign_score(cm.campaign_id, cm.user_id) as s from public.campaign_members cm join c on c.id = cm.campaign_id) select c.id, c.slug, c.title, c.tagline, greatest(0, c.ends_on - current_date + 1)::int, (select side from sc where user_id = auth.uid()), coalesce((select s from sc where user_id = auth.uid()), 0)::bigint, (select jsonb_agg(jsonb_build_object('key', cs.key, 'label', cs.label, 'walkers', (select count(*) from sc where sc.side = cs.key), 'total', coalesce((select sum(s) from sc where sc.side = cs.key), 0)) order by cs.sort) from public.campaign_sides cs where cs.campaign_id = c.id) from c $fn$;
revoke execute on function public.campaign_overview() from public, anon; grant execute on function public.campaign_overview() to authenticated;
create or replace function public.join_campaign(p_id uuid, p_side text) returns void language plpgsql security definer set search_path = public as $fn$ declare me uuid := auth.uid(); c public.campaigns; base int; begin if me is null then raise exception 'Sign in first'; end if; select * into c from public.campaigns where id = p_id and active and starts_on <= current_date and ends_on >= current_date; if c.id is null then raise exception 'That campaign is not running'; end if; if not exists (select 1 from public.campaign_sides where campaign_id = p_id and key = p_side) then raise exception 'Pick a side'; end if; if exists (select 1 from public.campaign_members where campaign_id = p_id and user_id = me) then raise exception 'You have already picked a side'; end if; select coalesce(s.steps, 0) into base from public.step_days s where s.user_id = me and s.day = current_date; insert into public.campaign_members (campaign_id, user_id, side, joined_on, base) values (p_id, me, p_side, current_date, coalesce(base, 0)); end $fn$;
-- A multi-city campaign: insert a campaigns row, then one campaign_sides row per city (key 'a','b','c',... and a label).

-- City World Cup (format = 'cup'): 8 capitals in two groups, 3 group matchdays, semi-finals, final.
-- Each match is decided by steps per walker over its days (members who have joined by then); win 3 pts, draw 1.
-- Group stage tiebreak: points, then total steps-per-walker across matches. Semi-finals: A1 v B2, B1 v A2.
alter table public.campaigns add column if not exists format text not null default 'duel';
alter table public.campaign_sides add column if not exists grp text;
create table if not exists public.campaign_matches (id uuid primary key default gen_random_uuid(), campaign_id uuid not null references public.campaigns(id) on delete cascade, round text not null, slot text, grp text, a text, b text, starts_on date not null, ends_on date not null);
alter table public.campaign_matches enable row level security;
create or replace function public.cup_avg(p_campaign uuid, p_side text, p_from date, p_to date) returns numeric language sql stable security definer set search_path = public as $fn$ select case when count(*) = 0 then 0 else round(sum(t.s)::numeric / count(*)) end from (select (select coalesce(sum(case when sd.day = cm.joined_on then greatest(sd.steps - cm.base, 0) else sd.steps end), 0) from public.step_days sd where sd.user_id = cm.user_id and sd.day between greatest(p_from, cm.joined_on) and p_to) as s from public.campaign_members cm where cm.campaign_id = p_campaign and cm.side = p_side and cm.joined_on <= p_to) t $fn$;
revoke execute on function public.cup_avg(uuid, text, date, date) from public, anon, authenticated;
create or replace function public.cup_standings(p_campaign uuid) returns table(grp text, key text, p integer, w integer, d integer, l integer, pts integer, tot numeric, pos integer) language sql stable security definer set search_path = public as $fn$ with m as (select cm.grp, cm.a, cm.b, public.cup_avg(p_campaign, cm.a, cm.starts_on, cm.ends_on) as aa, public.cup_avg(p_campaign, cm.b, cm.starts_on, cm.ends_on) as bb, (current_date > cm.ends_on) as done from public.campaign_matches cm where cm.campaign_id = p_campaign and cm.round like 'G%'), r as (select grp, a as k, done, aa as me, bb as other from m union all select grp, b, done, bb, aa from m), t as (select s.grp, s.key, count(r.k) filter (where r.done)::int as p, count(r.k) filter (where r.done and r.me > r.other)::int as w, count(r.k) filter (where r.done and r.me = r.other)::int as d, count(r.k) filter (where r.done and r.me < r.other)::int as l, coalesce(sum(r.me) filter (where r.done), 0) as tot from public.campaign_sides s left join r on r.k = s.key and r.grp = s.grp where s.campaign_id = p_campaign and s.grp is not null group by s.grp, s.key) select t.grp, t.key, t.p, t.w, t.d, t.l, (t.w * 3 + t.d)::int, t.tot, (row_number() over (partition by t.grp order by (t.w * 3 + t.d) desc, t.tot desc, t.key))::int from t $fn$;
revoke execute on function public.cup_standings(uuid) from public, anon, authenticated;
-- campaign_cup(p_id) returns jsonb { stage, round, current[], groups[], semis[], final, champion } or null. Defined live in the database; see the migration history.
